// ❌ OLD: Processing large image buffers directly on the main thread
// blocks user clicks, animations, and typing, triggering a severe INP failure.
function processImage(imageData) {
  // 2-second blocking loop on UI thread:
  for (let i = 0; i < imageData.data.length; i += 4) {
    imageData.data[i] = heavyColorCompute(imageData.data[i]);
  }
  ctx.putImageData(imageData, 0, 0);
}

// ✅ NEW: Transfer the raw buffer to a background Worker thread (0ms transfer),
// keeping the main thread free to handle 60fps animations and user input.
const worker = new Worker(new URL('./filter.worker.js', import.meta.url), { type: 'module' });

function processImage(imageData) {
  const buffer = imageData.data.buffer;
  // Transferable zero-copy handoff:
  worker.postMessage({ buffer, width: imageData.width, height: imageData.height }, [buffer]);
}

worker.onmessage = (event) => {
  const outputData = new ImageData(new Uint8ClampedArray(event.data.buffer), event.data.width, event.data.height);
  ctx.putImageData(outputData, 0, 0);
};
